    if (i === null) {
      panel.classList.remove('open'); panel.setAttribute('aria-hidden', 'true'); photo.classList.remove('open');
      return;
    }
    var p = CONFIG.shards[i];
    var accent = '#' + HOVER_COLORS[i].toString(16).padStart(6, '0');
    panel.style.setProperty('--accent', accent); photo.style.setProperty('--accent', accent);
    $('pSys').textContent = 'SYS://' + String(p.type).toUpperCase();
    $('pNum').textContent = pad2(i + 1) + ' / ' + pad2(N);
    pTitle.textContent = p.title; pTitle.dataset.text = p.title;
    $('pTag').textContent = p.tag;
    buildBody(p);
    pTitle.classList.remove('glitch'); void pTitle.offsetWidth; pTitle.classList.add('glitch');
